    def _convert_messages_to_bedrock_format(self, messages: List[BaseMessage]) -> List[Dict[str, str]]:
        """
        Convert LangChain messages to Bedrock API format.

        Args:
            messages: List of LangChain BaseMessage objects

        Returns:
            List of dictionaries in Bedrock API format
        """
        bedrock_messages = []

        for message in messages:
            if isinstance(message, HumanMessage):
                bedrock_messages.append({
                    "role": "user",
                    "content": message.content
                })
            elif isinstance(message, AIMessage):
                bedrock_messages.append({
                    "role": "assistant",
                    "content": message.content
                })
            elif isinstance(message, SystemMessage):
                # For Claude models, system messages can be handled as user messages
                # or through the system parameter in the request body
                bedrock_messages.append({
                    "role": "user",
                    "content": f"System: {message.content}"
                })
            else:
                # Default to user role for unknown message types
                bedrock_messages.append({
                    "role": "user",
                    "content": str(message.content)
                })

        return bedrock_messages

    def _generate(
        self,
        messages: List[BaseMessage],
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> ChatResult:
        """
        Generate chat response using AWS Bedrock.

        Args:
            messages: List of chat messages
            stop: List of stop sequences
            run_manager: Callback manager
            **kwargs: Additional parameters

        Returns:
            ChatResult containing the response
        """
        # Note: Bedrock streaming API does not support thinking content in streaming mode
        # When enable_thinking=True, force non-streaming to get thinking blocks
        use_streaming = self.streaming and not self.enable_thinking
        
        # If streaming is enabled, use streaming and collect all chunks
        if use_streaming:
            chunks = []
            full_content = ""
            for chunk in self._stream(messages, stop=stop, run_manager=run_manager, **kwargs):
                chunks.append(chunk)
                if chunk.message.content:
                    full_content += chunk.message.content

            # Strip reasoning tags from complete content if needed (for GPT-OSS models)
            if not self.include_reasoning:
                full_content = self._strip_reasoning(full_content)

            # Return final result with complete content
            final_message = AIMessage(content=full_content)
            return ChatResult(generations=[ChatGeneration(message=final_message)])

        # Non-streaming path
        # Convert messages to Bedrock format
        bedrock_messages = self._convert_messages_to_bedrock_format(messages)

        # Prepare request body
        body = {
            "messages": bedrock_messages,
            "max_tokens": kwargs.get("max_tokens", self.max_tokens),
            "anthropic_version": "bedrock-2023-05-31"
        }

        # Only include temperature if explicitly provided (either in kwargs or as instance variable)
        temperature = kwargs.get("temperature", self.temperature)
        if temperature is not None:
            body["temperature"] = temperature

        # Enable adaptive thinking for Anthropic models if requested
        if self.enable_thinking:
            # Set display mode - "summarized" shows thinking text, "omitted" hides it
            body["thinking"] = {
                "type": "adaptive",
                "display": "summarized" if self.include_reasoning else "omitted"
            }
            # Effort must be in a separate output_config object
            # Note: effort requires the beta header to work properly
            if self.thinking_effort:
                body["anthropic_beta"] = ["effort-2025-11-24"]
                body["output_config"] = {"effort": self.thinking_effort}

        # Add stop sequences if provided
        if stop:
            body["stop_sequences"] = stop

        try:
            # Make the API call
            response = self.client.invoke_model(
                modelId=self.model_id,
                contentType="application/json",
                accept="application/json",
                body=json.dumps(body).encode("utf-8")
            )

            # Parse response
            response_body = json.loads(response["body"].read().decode("utf-8"))

            # Extract the generated text
            generated_text = ""
            
            # Handle OpenAI-style responses (GPT-OSS models)
            if "choices" in response_body:
                for choice in response_body.get("choices", []):
                    message = choice.get("message", {})
                    if "content" in message:
                        content = message["content"]
                        # Strip reasoning tags if requested
                        if not self.include_reasoning:
                            content = self._strip_reasoning(content)
                        generated_text += content
            
            # Handle Anthropic-style responses (Claude models)
            elif "content" in response_body and len(response_body["content"]) > 0:
                # Iterate through all content blocks
                for content_block in response_body["content"]:
                    block_type = content_block.get("type", "")

                    # Handle text blocks
                    if block_type == "text" and "text" in content_block:
                        generated_text += content_block["text"]
                    # Handle thinking blocks - include if requested and non-empty
                    elif block_type == "thinking" and "thinking" in content_block:
                        thinking_content = content_block["thinking"]
                        if self.include_reasoning and thinking_content:
                            # Use same format as GPT-OSS for consistency
                            generated_text += f"\n<reasoning>\n{thinking_content}\n</reasoning>\n\n"

            # Create AIMessage
            message = AIMessage(content=generated_text)

            # Create ChatGeneration
            generation = ChatGeneration(message=message)

            return ChatResult(generations=[generation])

        except Exception as e:
            raise RuntimeError(f"Error calling AWS Bedrock: {str(e)}")

    def _stream(
        self,
        messages: List[BaseMessage],
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> Iterator[ChatGenerationChunk]:
        """
        Stream chat response using AWS Bedrock.
        """
        # Convert messages to Bedrock format
        bedrock_messages = self._convert_messages_to_bedrock_format(messages)

        # Prepare request body
        body = {
            "messages": bedrock_messages,
            "max_tokens": kwargs.get("max_tokens", self.max_tokens),
            "anthropic_version": "bedrock-2023-05-31"
        }

        # Only include temperature if explicitly provided (either in kwargs or as instance variable)
        temperature = kwargs.get("temperature", self.temperature)
        if temperature is not None:
            body["temperature"] = temperature

        # Enable adaptive thinking for Anthropic models if requested
        if self.enable_thinking:
            # Set display mode - "summarized" shows thinking text, "omitted" hides it
            body["thinking"] = {
                "type": "adaptive",
                "display": "summarized" if self.include_reasoning else "omitted"
            }
            # Effort must be in a separate output_config object
            # Note: effort requires the beta header to work properly
            if self.thinking_effort:
                body["anthropic_beta"] = ["effort-2025-11-24"]
                body["output_config"] = {"effort": self.thinking_effort}

        # Add stop sequences if provided
        if stop:
            body["stop_sequences"] = stop

        try:
            # Use streaming API
            response = self.client.invoke_model_with_response_stream(
                modelId=self.model_id,
                contentType="application/json",
                accept="application/json",
                body=json.dumps(body).encode("utf-8")
            )

            # Process streaming response
            for event in response["body"]:
                chunk = json.loads(event["chunk"]["bytes"].decode("utf-8"))
                
                # Handle OpenAI-style responses (GPT-OSS models)
                if "choices" in chunk:
                    for choice in chunk.get("choices", []):
                        delta = choice.get("delta", {})
                        if "content" in delta and delta["content"]:
                            text = delta["content"]
                            # Strip reasoning tags if requested
                            # Note: This works best when reasoning comes in complete chunks
                            # If tags are split, some may slip through to streaming output
                            # but final result will be clean (stripped in _generate)
                            if not self.include_reasoning:
                                text = self._strip_reasoning(text)
                            # Only yield if there's content after stripping
                            if text:
                                if run_manager:
                                    if hasattr(run_manager.on_llm_new_token, '__call__'):
                                        try:
                                            import asyncio
                                            if asyncio.iscoroutinefunction(run_manager.on_llm_new_token):
                                                pass
                                            else:
                                                run_manager.on_llm_new_token(text)
                                        except:
                                            run_manager.on_llm_new_token(text)
                                    else:
                                        run_manager.on_llm_new_token(text)
                                yield ChatGenerationChunk(message=AIMessageChunk(content=text))

                # Handle Anthropic-style responses (Claude models)
                elif chunk.get("type") == "content_block_delta":
                    delta = chunk.get("delta", {})
                    delta_type = delta.get("type", "")
                    
                    # Handle text deltas
                    if delta_type == "text_delta" and "text" in delta:
                        text = delta["text"]
                        if run_manager:
                            if hasattr(run_manager.on_llm_new_token, '__call__'):
                                try:
                                    import asyncio
                                    if asyncio.iscoroutinefunction(run_manager.on_llm_new_token):
                                        pass
                                    else:
                                        run_manager.on_llm_new_token(text)
                                except:
                                    run_manager.on_llm_new_token(text)
                            else:
                                run_manager.on_llm_new_token(text)
                        yield ChatGenerationChunk(message=AIMessageChunk(content=text))
                    # Note: thinking_delta chunks are NOT provided by Bedrock streaming API
                    # Thinking content is only available in non-streaming responses
                
                # Ignore other event types (message_start, content_block_start, content_block_stop, message_delta, message_stop)
                # These are just markers and don't contain content to yield

        except Exception as e:
            # Don't call _generate as fallback - it would cause infinite recursion
            # Instead, raise the error so it can be handled at a higher level
            raise RuntimeError(f"Error during streaming from AWS Bedrock: {str(e)}")

    async def _agenerate(
        self,
        messages: List[BaseMessage],
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> ChatResult:
        """
        Async generate chat response using AWS Bedrock.
        """
        # For now, run the sync version in a thread pool
        import asyncio
        loop = asyncio.get_event_loop()
        return await loop.run_in_executor(
            None,
            lambda: self._generate(messages, stop, run_manager, **kwargs)
        )

    async def _astream(
        self,
        messages: List[BaseMessage],
        stop: Optional[List[str]] = None,
        run_manager: Optional[CallbackManagerForLLMRun] = None,
        **kwargs: Any,
    ) -> Iterator[ChatGenerationChunk]:
        """
        Async stream chat response using AWS Bedrock.
        """
        # For now, run the sync version in a thread pool
        import asyncio
        loop = asyncio.get_event_loop()

        def sync_stream():
            return list(self._stream(messages, stop, run_manager, **kwargs))

        chunks = await loop.run_in_executor(None, sync_stream)
        for chunk in chunks:
            yield chunk

    def structured_generate(
        self,
        messages: List[BaseMessage],
        pydantic_model: BaseModel,
        tool_name: str = "structured_output",
        **kwargs: Any
    ) -> BaseModel:
        """
        Generate structured output using Bedrock tool calling.

        Args:
            messages: List of chat messages
            pydantic_model: Pydantic model class to structure the output
            tool_name: Name for the tool
            **kwargs: Additional parameters

        Returns:
            Instance of the pydantic_model with parsed data
        """
        # Convert Pydantic model to Bedrock tool schema
        tool_schema = _pydantic_to_bedrock_tool_schema(pydantic_model, tool_name)

        # Convert messages to Bedrock format
        bedrock_messages = self._convert_messages_to_bedrock_format(messages)

        # Build request body
        request_body = {
            "anthropic_version": "bedrock-2023-05-31",
            "max_tokens": self.max_tokens,
            "messages": bedrock_messages,
            "tools": [tool_schema],
            "tool_choice": {"type": "tool", "name": tool_name}
        }
        
        # Only include temperature if explicitly set
        if self.temperature is not None:
            request_body["temperature"] = self.temperature

        # Filter out parameters that aren't supported by Bedrock tool calling
        bedrock_kwargs = {}
        supported_params = {'system', 'anthropic_version'}
        for key, value in kwargs.items():
            if key in supported_params:
                bedrock_kwargs[key] = value

        # Add supported kwargs to request body
        request_body.update(bedrock_kwargs)

        try:
            # Call Bedrock
            response = self.client.invoke_model(
                modelId=self.model_id,
                body=json.dumps(request_body)
            )

            response_body = json.loads(response['body'].read())

            # Extract tool use from response
            content = response_body.get('content', [])
            for item in content:
                if item.get('type') == 'tool_use' and item.get('name') == tool_name:
                    tool_input = item.get('input', {})
                    # Parse the tool input into the Pydantic model
                    return pydantic_model(**tool_input)

            # If no tool use found, try to parse the text content as JSON
            for item in content:
                if item.get('type') == 'text':
                    try:
                        data = json.loads(item.get('text', '{}'))
                        return pydantic_model(**data)
                    except (json.JSONDecodeError, ValueError):
                        continue

            raise ValueError("No valid structured output found in response")

        except Exception as e:
            raise RuntimeError(f"Error in structured generation: {str(e)}")

    def with_structured_output(self, pydantic_model: BaseModel, **kwargs):
        """
        Return a wrapper that uses native structured output.
        This method makes ChatGovCloudBedrock compatible with LangChain's structured output interface.
        """
        class StructuredOutputWrapper:
            def __init__(self, chat_model, pydantic_model):
                self.chat_model = chat_model
                self.pydantic_model = pydantic_model

            def invoke(self, input_data, **invoke_kwargs):
                # Handle different input formats
                if hasattr(input_data, 'messages'):
                    messages = input_data.messages
                elif isinstance(input_data, list):
                    messages = input_data
                elif isinstance(input_data, str):
                    from langchain_core.messages import HumanMessage
                    messages = [HumanMessage(content=input_data)]
                else:
                    raise ValueError(f"Unsupported input type: {type(input_data)}")

                return self.chat_model.structured_generate(
                    messages=messages,
                    pydantic_model=self.pydantic_model,
                    **invoke_kwargs
                )

        return StructuredOutputWrapper(self, pydantic_model)

    @property
    def _llm_type(self) -> str:
        """Return type of chat model."""
        return "govcloud-bedrock"

    @property
    def _identifying_params(self) -> Dict[str, Any]:
        """Get identifying parameters."""
        return {
            "model_id": self.model_id,
            "region_name": self.region_name,
            "endpoint_url": self.endpoint_url,
            "max_tokens": self.max_tokens,
            "temperature": self.temperature,
        }


