class LlamaCpp:
    """
    A lightweight, LangChain-free wrapper around `llama_cpp.Llama`.

    This class replaces `langchain_community.llms.LlamaCpp` (which is deprecated,
    as `langchain-community` has been sunset). It exposes:

    - `client`: the underlying `llama_cpp.Llama` instance (used directly by OnPrem
      for `create_chat_completion` and for prompt truncation/tokenization).
    - `invoke(prompt, stop=..., **kwargs)`: returns the generated text as a string.
      When `streaming` is enabled, tokens are forwarded to any supplied `callbacks`
      (e.g., a streaming stdout handler) as they are generated.
    - `get_num_tokens(text)`: convenience token counter.

    Named arguments are the common generation/model parameters. Any additional
    keyword arguments (and the contents of `model_kwargs`) are forwarded directly
    to the `llama_cpp.Llama` constructor.
    """

    def __init__(
        self,
        model_path: str,
        max_tokens: Optional[int] = 256,
        temperature: Optional[float] = 0.8,
        top_p: Optional[float] = 0.95,
        top_k: Optional[int] = 40,
        repeat_penalty: Optional[float] = 1.1,
        stop: Optional[List[str]] = None,
        n_ctx: int = 512,
        n_batch: Optional[int] = 8,
        n_gpu_layers: Optional[int] = None,
        verbose: bool = False,
        streaming: bool = True,
        callbacks: Optional[List[Any]] = None,
        grammar_path: Optional[str] = None,
        grammar: Optional[Any] = None,
        model_kwargs: Optional[Dict[str, Any]] = None,
        **kwargs: Any,
    ):
        try:
            from llama_cpp import Llama, LlamaGrammar
        except ImportError:
            raise ImportError(
                "Could not import llama-cpp-python library. "
                "Please install it to use local GGUF models: pip install llama-cpp-python"
            )

        self.model_path = model_path
        # Generation defaults (applied on each invoke call)
        self.max_tokens = max_tokens
        self.temperature = temperature
        self.top_p = top_p
        self.top_k = top_k
        self.repeat_penalty = repeat_penalty
        self.stop = stop or []
        self.streaming = streaming
        self.verbose = verbose
        self.callbacks = callbacks or []

        # Handle grammar (mutually exclusive with grammar_path)
        if grammar and grammar_path:
            raise ValueError(
                "Can only pass in one of grammar and grammar_path. "
                f"Received {grammar=} and {grammar_path=}."
            )
        if isinstance(grammar, str):
            self.grammar = LlamaGrammar.from_string(grammar)
        elif grammar_path:
            self.grammar = LlamaGrammar.from_file(grammar_path)
        else:
            self.grammar = grammar

        # Assemble constructor params for llama_cpp.Llama. Named model params are
        # included explicitly; any extra kwargs (and model_kwargs) are passed through.
        model_params: Dict[str, Any] = {
            "n_ctx": n_ctx,
            "n_batch": n_batch,
            "verbose": verbose,
        }
        # Only include n_gpu_layers when explicitly provided (backwards compatibility)
        if n_gpu_layers is not None:
            model_params["n_gpu_layers"] = n_gpu_layers
        model_params.update(model_kwargs or {})
        model_params.update(kwargs)

        try:
            self.client = Llama(model_path, **model_params)
        except Exception as e:
            raise ValueError(
                f"Could not load Llama model from path: {model_path}. Received error {e}"
            )

    def _generation_params(self, stop: Optional[List[str]] = None) -> Dict[str, Any]:
        """Build the parameter dict passed to each llama_cpp generation call."""
        params: Dict[str, Any] = {
            "max_tokens": self.max_tokens,
            "temperature": self.temperature,
            "top_p": self.top_p,
            "top_k": self.top_k,
            "repeat_penalty": self.repeat_penalty,
            "stop": stop if stop else self.stop,
        }
        if self.grammar:
            params["grammar"] = self.grammar
        return params

    def invoke(self, prompt, stop: Optional[List[str]] = None,
               use_chat_template: bool = False, **kwargs: Any) -> str:
        """
        Generate a response and return it as a string.

        `prompt` may be either:

        - a list of chat-message dicts (e.g., ``[{"role": "user", "content": ...}]``),
          which is routed through `create_chat_completion` so the GGUF-embedded chat
          template is applied automatically; or
        - a string. If `use_chat_template` is True, the string is wrapped as a single
          user message and routed through `create_chat_completion` (auto chat template).
          Otherwise, the (already-formatted) string is sent as a raw completion.

        When `streaming` is enabled, tokens are forwarded to any registered
        callbacks via `on_llm_new_token` as they are generated.
        """
        # message-list prompts (or string prompts requesting chat templating)
        if isinstance(prompt, list):
            return self.create_chat_completion(prompt, stop=stop, **kwargs)
        if use_chat_template:
            return self.create_chat_completion(
                [{"role": "user", "content": prompt}], stop=stop, **kwargs
            )

        params = {**self._generation_params(stop), **kwargs}

        if self.streaming:
            combined = ""
            for part in self.client(prompt=prompt, stream=True, **params):
                token = part["choices"][0]["text"]
                combined += token
                for cb in self.callbacks:
                    if hasattr(cb, "on_llm_new_token"):
                        cb.on_llm_new_token(token)
            return combined

        result = self.client(prompt=prompt, **params)
        return result["choices"][0]["text"]

    def create_chat_completion(self, messages: List[Dict[str, Any]],
                               stop: Optional[List[str]] = None, **kwargs: Any) -> str:
        """
        Generate a response for a list of chat messages and return it as a string.

        This uses llama.cpp's `create_chat_completion`, which applies the chat
        template embedded in the GGUF metadata (e.g., Gemma, Llama 3, Mistral).
        This lets modern models work without a manually-specified `prompt_template`.

        When `streaming` is enabled, tokens are forwarded to any registered
        callbacks via `on_llm_new_token` as they are generated.
        """
        params = {**self._generation_params(stop), **kwargs}

        if self.streaming:
            combined = ""
            for part in self.client.create_chat_completion(messages, stream=True, **params):
                delta = part["choices"][0].get("delta", {})
                token = delta.get("content") or ""
                if token:
                    combined += token
                    for cb in self.callbacks:
                        if hasattr(cb, "on_llm_new_token"):
                            cb.on_llm_new_token(token)
            return combined

        result = self.client.create_chat_completion(messages, **params)
        return result["choices"][0]["message"]["content"]

    def get_num_tokens(self, text: str) -> int:
        """Return the number of tokens in `text`."""
        return len(self.client.tokenize(text.encode("utf-8")))

    def as_runnable(self, use_chat_template: bool = False):
        """
        Return a `langchain_core`-compatible LLM (a `Runnable`) that delegates to
        this instance. Useful for interop with LangChain constructs (e.g., legacy
        chains like `LLMChain`) that require a `Runnable` LLM. The core `LlamaCpp`
        class itself remains LangChain-free for normal use.

        If `use_chat_template` is True, prompts are routed through the GGUF-embedded
        chat template (via `create_chat_completion`). Set this when no explicit
        prompt template is being applied to the prompt text.
        """
        return _LlamaCppRunnable(llamacpp=self, use_chat_template=use_chat_template)


class _LlamaCppRunnable(LLM):
    """
    A thin `langchain_core` LLM adapter that delegates to a `LlamaCpp` instance.

    This exists only for interop with LangChain constructs that require a
    `Runnable` LLM (e.g., the legacy `LLMChain` used by the summarizer). It is
    built on `langchain_core` (not the deprecated `langchain_community`).
    """

    llamacpp: Any = None
    use_chat_template: bool = False

    def _call(self, prompt: str, stop: Optional[List[str]] = None,
              run_manager: Optional[CallbackManagerForLLMRun] = None, **kwargs: Any) -> str:
        return self.llamacpp.invoke(prompt, stop=stop,
                                    use_chat_template=self.use_chat_template, **kwargs)

    @property
    def _identifying_params(self) -> Dict[str, Any]:
        return {"model_path": getattr(self.llamacpp, "model_path", None)}

    @property
    def _llm_type(self) -> str:
        return "onprem-llamacpp"




# %% ../../nbs/00_llm.backends.ipynb #b3a73e89-fd25-4d83-8910-b32e8c6acb6a
class HFPipeline:
    """
    A lightweight, LangChain-free wrapper around a Hugging Face `transformers`
    text-generation `pipeline`.

    This replaces `langchain_huggingface`'s `ChatHuggingFace`/`HuggingFacePipeline`
    for the local-transformers generation path. It exposes:

    - `pipeline`: the underlying `transformers` pipeline (used for tokenizer access,
      `generation_config`, and prompt truncation).
    - `invoke(prompt, stop=..., **kwargs)`: returns generated text as a string.
      Applies the tokenizer's chat template (as a single user message) when available,
      and forwards `stop` via the pipeline's `stop_strings` argument.
    - `get_num_tokens(text)`: convenience token counter.
    """

    def __init__(self, model_id: str, max_tokens: int = 512, mute_stream: bool = False,
                 tokenizer: Any = None, **kwargs: Any):
        """
        Build a Hugging Face text-generation pipeline from `model_id`.

        Any extra keyword arguments are forwarded to `transformers.pipeline`
        (e.g., `temperature`, `device_map`, `torch_dtype`, `model_kwargs`).
        """
        from transformers import pipeline, TextStreamer, AutoTokenizer

        tokenizer = tokenizer if tokenizer is not None else AutoTokenizer.from_pretrained(model_id)
        streamer = TextStreamer(tokenizer)

        pipe = pipeline(
            'text-generation',
            model_id,
            tokenizer=tokenizer,
            streamer=streamer if not mute_stream else None,
            max_new_tokens=max_tokens,
            return_full_text=False,
            do_sample=True if kwargs.get('temperature', 0.8) > 0.0 else False,
            **kwargs,
        )

        # Ensure pad_token_id is set (avoids generation warnings/errors)
        model = pipe.model
        if not model.generation_config.pad_token_id:
            tokenid = model.generation_config.eos_token_id
            model.generation_config.pad_token_id = tokenid[0] if isinstance(tokenid, list) else tokenid

        self.pipeline = pipe
        self.tokenizer = tokenizer
        self.model_id = model_id

    def invoke(self, prompt, stop: Optional[List[str]] = None, **kwargs: Any) -> str:
        """
        Generate text and return it as a string.

        `prompt` may be a string or a list of chat-message dicts. When the
        tokenizer defines a chat template, a string prompt is wrapped as a single
        user message; a message list is passed through as-is.
        """
        tokenizer = self.pipeline.tokenizer
        if isinstance(prompt, list):
            # already a list of chat messages
            pipe_input = prompt
        elif getattr(tokenizer, "chat_template", None):
            # wrap string as a single user message (fix for #113/#114)
            pipe_input = [{"role": "user", "content": prompt}]
        else:
            pipe_input = prompt

        # Normalize max_tokens -> max_new_tokens for the transformers pipeline
        if "max_tokens" in kwargs:
            kwargs["max_new_tokens"] = kwargs.pop("max_tokens")

        output = self.pipeline(
            pipe_input,
            stop_strings=stop if stop else None,
            tokenizer=tokenizer,
            **kwargs,
        )
        return output[0]["generated_text"]

    def get_num_tokens(self, text: str) -> int:
        """Return the number of tokens in `text`."""
        return len(self.pipeline.tokenizer.encode(text, add_special_tokens=False))

    def as_runnable(self, **kwargs):
        """
        Return a `langchain_core`-compatible LLM (a `Runnable`) that delegates to
        this instance, for interop with LangChain constructs (e.g., legacy chains,
        or the Extractor's fix LLM) that require a `Runnable`.

        Extra keyword arguments (e.g., `use_chat_template`, accepted by other
        backends) are ignored: HFPipeline always applies the tokenizer's chat
        template (when present) inside `invoke`.
        """
        return _HFPipelineRunnable(hfpipeline=self)


class _HFPipelineRunnable(LLM):
    """A thin `langchain_core` LLM adapter that delegates to an `HFPipeline`."""

    hfpipeline: Any = None

    def _call(self, prompt: str, stop: Optional[List[str]] = None,
              run_manager: Optional[CallbackManagerForLLMRun] = None, **kwargs: Any) -> str:
        return self.hfpipeline.invoke(prompt, stop=stop, **kwargs)

    @property
    def _identifying_params(self) -> Dict[str, Any]:
        return {"model_id": getattr(self.hfpipeline, "model_id", None)}

    @property
    def _llm_type(self) -> str:
        return "onprem-hfpipeline"
